# all class and function definitions in the code file, if any
class ATMMachine:
    def __init__(self):
        self._handler = RequestHandler.getHandlingChain()

    def getAmount(self, amount):
        return self._handler.handleRequest(amount)

class RequestHandler:
    def __init__(self, nextHandler):
        self._next = nextHandler

    @staticmethod
    def getHandlingChain():
        handler = RequestHandlerForFive(None)
        handler = RequestHandlerForTen(handler)
        handler = RequestHandlerForTwenty(handler)
        handler = RequestHandlerForFifty(handler)
        return handler

    def handleRequest(self, amount):
        if amount < 0: raise Exception("Illegal Argument")
        if amount == 0: return []
        if amount % 5 != 0: raise Exception("Amount should be multiple of 5")

        denom = self.denomination()
        value = denom.value
        addSingleNote = False

        if amount >= value:
            noteList = self.handleRequest(amount - value)
            addSingleNote = True
        else:
            if self._next is not None:
                noteList = self._next.handleRequest(amount)
            else:
                raise Exception("Illegal State")

        if addSingleNote: noteList.append(denom)

        return noteList

    def denomination(self):
        raise NotImplementedError

