Given the following input:

{'field': [['c', 'c', 'c', 'c', 'c', 'c'], ['c', 'c', 'w', 'c', 'c', 'c'], ['c', 'c', 'c', 'w', 'c', 'c'], ['c', 'c', 'c', 'c', 'c', 'c'], ['c', 'w', 'c', 'c', 'c', 'w']]}

