# import necessary packages
import random

# main function
def main_solution(field):
    # Convert the input field to a list of lists if it's not already
    if not isinstance(field, list) or not all(isinstance(row, list) for row in field):
        raise ValueError("Input field must be a 2D list (list of lists).")

    # Create a copy of the field to avoid modifying the original input
    hydrated_field = [row[:] for row in field]

    # Hydrate the crops around each water source
    for a in range(len(hydrated_field)):
        for b in range(len(hydrated_field[0])):
            if hydrated_field[a][b] == "w":
                for c in range(-1, 2):
                    for d in range(-1, 2):
                        if 0 <= a + c < len(hydrated_field) and 0 <= b + d < len(hydrated_field[0]) and hydrated_field[a + c][b + d] != "w":
                            hydrated_field[a + c][b + d] = "#"

    # Check if there are any crops left unhydrated
    is_hydrated = not any('c' in row for row in hydrated_field)

    # Return the result as a boolean
    return is_hydrated
